<template>
  <section class="lab-page" v-loading="loading">
    <header class="lab-header">
      <div><h1>理论学习</h1><p>选择一个专题进入学习与作答。</p></div>
      <div class="catalog-actions"><span>{{ topics.length }} 个专题 · {{ questions.length }} 道复合题</span><router-link class="primary-link" :to="theoryHistoryPath()">我的作答 →</router-link></div>
    </header>
    <p v-if="notice" class="notice" role="alert">{{ notice }}</p>
    <nav class="topic-grid" aria-label="六个理论专题">
      <router-link v-for="topic in pageView.items" :key="topic.id" :to="theoryTopicPath(topic.id)" class="topic-card">
        <span class="topic-num">{{ String(topic.id).padStart(2,'0') }}</span>
        <span><strong>{{ topic.title }}</strong><small>{{ questions.filter(q=>q.topic===topic.id).length }} 道题 · {{ theoryPlatformName(topic.id) }}</small></span><span class="topic-arrow">进入 →</span>
      </router-link>
    </nav>
    <ListPager :page="pageView.page" :total="pageView.total" @change="changePage"/>
    <el-empty v-if="!loading&&!questions.length" description="null"/>
  </section>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import ListPager from '@/components/ListPager.vue'
import { paginate,pageNumber } from '@/domain/pagination'
import { getLabQuestions } from '@/api/labTopics'
import { theoryTopicPath, theoryHistoryPath, theoryPlatformName } from '@/domain/theoryNavigation'
const route=useRoute(),router=useRouter(),questions=ref([]),loading=ref(false),notice=ref('')
const topics=computed(()=>[...new Map(questions.value.map(q=>[q.topic,q.topic_info])).values()].sort((a,b)=>a.id-b.id))
const page=ref(pageNumber(route.query.page))
const pageView=computed(()=>paginate(topics.value,page.value))
function changePage(value){page.value=value;router.push({path:route.path,query:{page:String(value)}})}
watch(()=>route.query.page,value=>{page.value=pageNumber(value)})
onMounted(async()=>{
  loading.value=true
  try{
    questions.value=await getLabQuestions()
    const requested=questions.value.find(q=>q.key===route.query.q)
    if(requested)await router.replace({path:theoryTopicPath(requested.topic),query:{q:requested.key}})
  }catch{notice.value='专题加载失败，请重试。'}finally{loading.value=false}
})
</script>
